// @ts-check
// In-game POI editor asset catalog: loads the game's models, flats, items, and creatures once from
// `public/poi/asset-catalogue.json` (generated by `tools/poiAssetCatalogue.mjs`) and searches them in memory. Saves the
// builder's favorites and recent picks in `localStorage`.

import { APP_ROOT } from '../platform/appRoot.js';

/**
 * One catalog entry. `id` is `model:<ARCH3D id>`, `flat:<archive>.<record>`, `item:<template>`, or `creature:<enemy
 * id>`; `placing` picks the placer in `poi/poiAssetPlace.js` (an uploaded mesh, a v2 flat row, or a DM encounter).
 * `figure` marks an NPC flat fixed at scale 1, and `standIn` names a built-in fallback.
 * @typedef {{ id: string, name: string, category: string, tags: string[], kind: 'model' | 'flat' | 'item' | 'creature', placing: 'upload' | 'billboard' | 'mount' | 'paperdoll' | 'encounter', source: string,
 *   model?: number, flat?: [number, number], figure?: boolean, template?: number, group?: number, creature?: number, standIn?: string, duplicate?: boolean, missing?: string }} PoiAsset
 */

/** The categories, in the order the browser lists them. */
export const POI_ASSET_CATEGORIES = Object.freeze({
  buildings: 'Buildings', furniture: 'Furniture', dungeon: 'Dungeon pieces', outdoor: 'Outdoors', ships: 'Ships',
  models: 'Other models', nature: 'Trees and plants', lights: 'Lights', decor: 'Decorations', people: 'People',
  textures: 'Wall and ground textures', underwater: 'Underwater', festival: 'Witches\' Festival', 'mod-flats': 'Mod pictures',
  weapons: 'Weapons', armor: 'Armor',
  clothing: 'Clothing', items: 'Other items', trophies: 'Trophies', monsters: 'Monsters', classes: 'Class enemies',
});

/** Where the game build serves the catalog. */
export const POI_ASSET_CATALOGUE_PATH = 'poi/asset-catalogue.json';

const DEFAULT_PLACING = Object.freeze({ model: 'upload', flat: 'billboard', item: 'paperdoll', creature: 'encounter' });
/** Default `source` label for a catalog entry when its packed row omits `source`. */
function defaultSource(/** @type {string} */ kind, /** @type {number} */ n) {
  if (kind === 'model') return 'ARCH3D.BSA';
  if (kind === 'flat') return `TEXTURE.${String(n).padStart(3, '0')}`;
  if (kind === 'item') return 'src/systems/item/itemTemplatesData.js';
  return 'src/characters/enemy/enemyBasics.js';
}

/** Unpacks catalog rows (`[id, name, category, tags, extra]` from `packPoiAssetCatalogue` in
 *  `poi/poiAssetCatalogueBuild.js`) into `PoiAsset` objects. @param {any} json @returns {PoiAsset[]} */
export function hydratePoiAssets(json) {
  /** @type {PoiAsset[]} */
  const out = [];
  for (const row of Array.isArray(json?.entries) ? json.entries : []) {
    if (!Array.isArray(row) || typeof row[0] !== 'string') continue;
    const [id, name, category, tags, extra = {}] = row;
    const colon = id.indexOf(':');
    const kind = /** @type {PoiAsset['kind']} */ (id.slice(0, colon));
    if (!(kind in DEFAULT_PLACING)) continue;
    const ref = id.slice(colon + 1);
    const nums = ref.split('.').map(Number);
    /** @type {any} */
    const a = { id, name: String(name), category: String(category), tags: Array.isArray(tags) ? tags.map(String) : [], kind, placing: DEFAULT_PLACING[kind], source: defaultSource(kind, nums[0]), ...extra };
    if (kind === 'model') a.model = nums[0];
    else if (kind === 'flat') a.flat = [nums[0], nums[1]];
    else if (kind === 'item') a.template = nums[0];
    else a.creature = nums[0];
    out.push(a);
  }
  return out;
}

const words = (/** @type {string} */ s) => String(s).toLowerCase().split(/[^a-z0-9.']+/).filter(Boolean);

/**
 * Builds the in-memory catalog with entry lookup by ID, facet counts, and search.
 * @param {any} json parsed catalog JSON @param {{ hide?: (a: PoiAsset) => boolean }} [o] `hide` excludes entries (such
 * as nude figures while Show Nudity is off)
 */
export function createPoiAssetCatalogue(json, { hide = () => false } = {}) {
  const assets = hydratePoiAssets(json).filter((a) => !hide(a));
  const byId = new Map(assets.map((a) => [a.id, a]));
  const hay = assets.map((a) => `${a.name} ${a.id} ${a.category} ${a.tags.join(' ')}`.toLowerCase());
  /** Counts by kind, category, and tag over every entry. */
  function facets() {
    const f = { kind: new Map(), category: new Map(), tag: new Map() };
    for (const a of assets) {
      f.kind.set(a.kind, (f.kind.get(a.kind) ?? 0) + 1);
      f.category.set(a.category, (f.category.get(a.category) ?? 0) + 1);
      for (const t of a.tags) f.tag.set(t, (f.tag.get(t) ?? 0) + 1);
    }
    return f;
  }
  /**
   * The entries matching every word of `q` (in the name, the id, the category, or a tag) and every filter, in catalog
   * order. `ids` limits the search to a set (favorites, recents).
   * @param {{ q?: string, kind?: string | null, category?: string | null, tag?: string | null, ids?: Set<string> | null }} [f]
   */
  function search({ q = '', kind = null, category = null, tag = null, ids = null } = {}) {
    const ws = words(q);
    /** @type {PoiAsset[]} */
    const out = [];
    for (let i = 0; i < assets.length; i++) {
      const a = assets[i];
      if (kind && a.kind !== kind) continue;
      if (category && a.category !== category) continue;
      if (tag && !a.tags.includes(tag)) continue;
      if (ids && !ids.has(a.id)) continue;
      if (ws.length && !ws.every((w) => hay[i].includes(w))) continue;
      out.push(a);
    }
    return out;
  }
  return {
    assets, facets, search,
    get: (/** @type {string} */ id) => byId.get(id) ?? null,
    missing: Array.isArray(json?.missing) ? json.missing : [],
    duplicates: Array.isArray(json?.duplicates) ? json.duplicates : [],
  };
}

/** @type {Promise<any> | null} */
let loading = null;
/** Fetches the catalog JSON once per page load (retrying on future calls if the fetch fails) and returns the parsed
 *  JSON or null.
 *  @param {(url: string) => Promise<any>} [get] */
export function loadPoiAssetCatalogue(get = (url) => fetch(url).then((r) => (r.ok ? r.json() : null))) {
  if (!loading) {
    const url = new URL(POI_ASSET_CATALOGUE_PATH, APP_ROOT ?? globalThis.document?.baseURI ?? 'http://localhost/').href;
    loading = get(url).then((j) => j ?? null, () => null).then((j) => { if (!j) loading = null; return j; });
  }
  return loading;
}

const PREFS_KEY = 'bunnyfall.poi.assets';
export const POI_ASSET_RECENT_MAX = 40;
/** Tracks the builder's favorite and recent asset IDs in `storage` (`localStorage` or any `{ getItem, setItem }`
 *  store), falling back to in-memory state for the current page if storage is unavailable. */
export function createPoiAssetPrefs(/** @type {any} */ storage) {
  let p = { favorites: /** @type {string[]} */ ([]), recent: /** @type {string[]} */ ([]) };
  try {
    const raw = JSON.parse(storage?.getItem(PREFS_KEY) ?? 'null');
    if (raw && typeof raw === 'object') {
      p = { favorites: Array.isArray(raw.favorites) ? raw.favorites.filter((/** @type {any} */ x) => typeof x === 'string') : [],
        recent: Array.isArray(raw.recent) ? raw.recent.filter((/** @type {any} */ x) => typeof x === 'string').slice(0, POI_ASSET_RECENT_MAX) : [] };
    }
  } catch { /* unreadable storage: start empty */ }
  const save = () => { try { storage?.setItem(PREFS_KEY, JSON.stringify(p)); } catch { /* full or blocked: this page only */ } };
  return {
    favorites: () => new Set(p.favorites),
    isFavorite: (/** @type {string} */ id) => p.favorites.includes(id),
    toggleFavorite(/** @type {string} */ id) { const i = p.favorites.indexOf(id); if (i < 0) p.favorites.push(id); else p.favorites.splice(i, 1); save(); return i < 0; },
    recent: () => [...p.recent],
    noteUsed(/** @type {string} */ id) { p.recent = [id, ...p.recent.filter((x) => x !== id)].slice(0, POI_ASSET_RECENT_MAX); save(); },
  };
}

/** The rows a virtual grid draws for a scroll position: rows `[first, last)`, entries `[from, to)`, and the full height. */
export function visibleRows(/** @type {number} */ total, /** @type {number} */ perRow, /** @type {number} */ rowH, /** @type {number} */ scrollTop, /** @type {number} */ viewH, overscan = 2) {
  const rows = Math.ceil(total / perRow);
  const first = Math.max(0, Math.floor(scrollTop / rowH) - overscan);
  const last = Math.min(rows, Math.ceil((scrollTop + viewH) / rowH) + overscan);
  return { first, last, from: first * perRow, to: Math.min(total, last * perRow), height: rows * rowH };
}
